// compile_qnn.cpp
// Encrypts build/model_context.bin (generated by qnn-context-binary-generator)
// using AES-256-ECB, producing model_context.bin.enc.
// Usage: ./compile_qnn <password> [input.bin] [output.bin.enc]

#include <openssl/evp.h>
#include <openssl/sha.h>
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <fstream>
#include <vector>
#include <iostream>
#include <string>

// Derives an AES-256 key from the password (SHA-256 of the password,
// same pattern used for ONNX/OpenVINO/TFLite in this repo)
static void derive_key(const std::string& password, unsigned char* key /*32 bytes*/) {
    SHA256(reinterpret_cast<const unsigned char*>(password.data()),
           password.size(), key);
}

static std::vector<unsigned char> read_file(const std::string& path) {
    std::ifstream f(path, std::ios::binary | std::ios::ate);
    if (!f) {
        std::cerr << "Error: cannot open " << path << std::endl;
        exit(1);
    }
    std::streamsize size = f.tellg();
    f.seekg(0, std::ios::beg);
    std::vector<unsigned char> buf(size);
    if (!f.read(reinterpret_cast<char*>(buf.data()), size)) {
        std::cerr << "Error: failed to read " << path << std::endl;
        exit(1);
    }
    return buf;
}

static void write_file(const std::string& path, const unsigned char* data, size_t len) {
    std::ofstream f(path, std::ios::binary);
    if (!f) {
        std::cerr << "Error: cannot write " << path << std::endl;
        exit(1);
    }
    f.write(reinterpret_cast<const char*>(data), len);
}

int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0]
                  << " <password> [input=build/model_context.bin] [output=build/model_context.bin.enc]"
                  << std::endl;
        return 1;
    }

    std::string password    = argv[1];
    std::string input_path  = (argc > 2) ? argv[2] : "build/model_context.bin";
    std::string output_path = (argc > 3) ? argv[3] : "build/model_context.bin.enc";

    unsigned char key[32];
    derive_key(password, key);

    std::vector<unsigned char> plaintext = read_file(input_path);

    // Output buffer: ECB with PKCS7 padding, so up to +16 bytes
    std::vector<unsigned char> ciphertext(plaintext.size() + EVP_MAX_BLOCK_LENGTH);
    int out_len1 = 0, out_len2 = 0;

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        std::cerr << "Error: EVP_CIPHER_CTX_new failed" << std::endl;
        return 1;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), nullptr, key, nullptr) != 1) {
        std::cerr << "Error: EVP_EncryptInit_ex failed" << std::endl;
        EVP_CIPHER_CTX_free(ctx);
        return 1;
    }

    if (EVP_EncryptUpdate(ctx, ciphertext.data(), &out_len1,
                           plaintext.data(), static_cast<int>(plaintext.size())) != 1) {
        std::cerr << "Error: EVP_EncryptUpdate failed" << std::endl;
        EVP_CIPHER_CTX_free(ctx);
        return 1;
    }

    if (EVP_EncryptFinal_ex(ctx, ciphertext.data() + out_len1, &out_len2) != 1) {
        std::cerr << "Error: EVP_EncryptFinal_ex failed" << std::endl;
        EVP_CIPHER_CTX_free(ctx);
        return 1;
    }

    EVP_CIPHER_CTX_free(ctx);

    size_t total_len = out_len1 + out_len2;
    write_file(output_path, ciphertext.data(), total_len);

    std::cout << "Encrypted " << input_path << " (" << plaintext.size()
              << " bytes) -> " << output_path << " (" << total_len
              << " bytes)" << std::endl;

    return 0;
}